-- P8R1 / PREPARATION ONLY. No executable runner is supplied.
-- Require explicit BEGIN before this file; leave execution permission unset by default.
DO $preflight$
BEGIN
  IF current_setting('idn.p8r.execution_permission', true)
       IS DISTINCT FROM 'APPROVED_DISPOSABLE_REHEARSAL_P8R1'
     OR left(current_database(),13) <> 'idn_p8r_test_'
     OR current_setting('transaction_isolation') <> 'read committed'
     OR current_setting('transaction_read_only') <> 'off' THEN
    RAISE EXCEPTION 'P8R1 is review-only: explicit disposable rehearsal authorization required';
  END IF;
  IF to_regnamespace('migration_review') IS NOT NULL THEN
    RAISE EXCEPTION 'Fresh predecessor required: migration_review already exists';
  END IF;
END
$preflight$;
-- An ON COMMIT DROP token makes accidental autocommit use fail at the next statement.
CREATE TEMP TABLE p8r_context(package text PRIMARY KEY) ON COMMIT DROP;
INSERT INTO p8r_context VALUES ('P8R1');
CREATE FUNCTION pg_temp.p8r_guard() RETURNS void LANGUAGE plpgsql AS $guard$
BEGIN
  IF current_setting('idn.p8r.execution_permission', true)
       IS DISTINCT FROM 'APPROVED_DISPOSABLE_REHEARSAL_P8R1'
     OR left(current_database(),13) <> 'idn_p8r_test_'
     OR current_setting('transaction_isolation') <> 'read committed'
     OR NOT EXISTS (SELECT 1 FROM pg_temp.p8r_context WHERE package='P8R1') THEN
    RAISE EXCEPTION 'Wrong execution context';
  END IF;
END $guard$;
SELECT pg_temp.p8r_guard();
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
SELECT pg_advisory_xact_lock(7092026, 801);
SET LOCAL timezone = 'UTC';
SET LOCAL search_path = public, pg_catalog;
-- Explicit table locks prevent concurrent schema/writer drift during a future rehearsal.
LOCK TABLE public.company, public.contact, public.task, public.list,
 public.campaign_send, public.linkedin_monitor_config, public.linkedin_snapshot,
 public.list_binding, public.external_ref IN ACCESS EXCLUSIVE MODE;
