schema":"pg_catalog","udt_name":"uuid","is_nullable":"YES","column_default":null},{"table_name":"task","column_name":"person_id","udt_schema":"pg_catalog","udt_name":"uuid","is_nullable":"YES","column_default":null},{"table_name":"task","column_name":"event_id","udt_schema":"pg_catalog","udt_name":"uuid","is_nullable":"YES","column_default":null},{"table_name":"task","column_name":"due_at","udt_schema":"pg_catalog","udt_name":"timestamptz","is_nullable":"YES","column_default":null},{"table_name":"task","column_name":"completed_at","udt_schema":"pg_catalog","udt_name":"timestamptz","is_nullable":"YES","column_default":null},{"table_name":"task","column_name":"raw","udt_schema":"pg_catalog","udt_name":"jsonb","is_nullable":"NO","column_default":"'{}'::jsonb"},{"table_name":"task","column_name":"created_at","udt_schema":"pg_catalog","udt_name":"timestamptz","is_nullable":"NO","column_default":"now()"},{"table_name":"task","column_name":"updated_at","udt_schema":"pg_catalog","udt_name":"timestamptz","is_nullable":"NO","column_default":"now()"}]$catalog$::jsonb;
        difference_count integer;
BEGIN
  WITH e AS (
    SELECT * FROM jsonb_to_recordset(expected)
    AS x(table_name text,column_name text,udt_schema text,udt_name text,
         is_nullable text,column_default text)
  ), actual AS (
    SELECT c.table_name::text,c.column_name::text,c.udt_schema::text,c.udt_name::text,
           c.is_nullable::text,
           case when c.column_default = 'pg_catalog.gen_random_uuid()'
                then 'gen_random_uuid()' else c.column_default::text end
    FROM information_schema.columns c
    WHERE c.table_schema='public'
      AND c.table_name IN (SELECT DISTINCT table_name FROM e)
  ), differences AS (
    (SELECT * FROM e EXCEPT SELECT * FROM actual)
    UNION ALL
    (SELECT * FROM actual EXCEPT SELECT * FROM e)
  ) SELECT count(*) INTO difference_count FROM differences;
  IF difference_count <> 0 THEN
    RAISE EXCEPTION 'Pinned selected-column predecessor differs (% rows)',difference_count;
  END IF;
  IF EXISTS (SELECT 1 FROM public.campaign_send)
     OR EXISTS (SELECT 1 FROM public.outreach_event) THEN
    RAISE EXCEPTION 'Nonempty email history: separately reviewed conversion/import required';
  END IF;
  IF EXISTS (SELECT 1 FROM public.external_ref WHERE source_system='engager_v1'
      AND entity_table IN ('company','contact','list')
      GROUP BY entity_table,entity_id HAVING count(*)>1) THEN
    RAISE EXCEPTION 'Ambiguous Engager lineage; resolve before proposing backfills';
  END IF;
  IF to_regclass('public.campaign_send_event') IS NOT NULL
     OR to_regclass('public.linkedin_signal') IS NOT NULL
     OR to_regclass('public.list_filter') IS NOT NULL
     OR to_regclass('public.list_version') IS NOT NULL
     OR to_regprocedure('public.update_campaign_send_rollups()') IS NOT NULL
     OR to_regtype('public.send_status') IS NOT NULL THEN
    RAISE EXCEPTION 'Phase 8 already present: this is not a patch for the old Phase 8 branch';
  END IF;
  IF to_regclass('public.companies') IS NULL OR to_regclass('public.contacts') IS NULL
     OR to_regclass('public.lists') IS NULL OR to_regclass('public.campaign_sends') IS NULL
     OR to_regclass('public.v_taxonomy') IS NULL
     OR to_regclass('stg_engager.companies') IS NULL
     OR to_regclass('stg_engager.contacts') IS NULL
     OR to_regclass('stg_engager.lists') IS NULL THEN
    RAISE EXCEPTION 'Required predecessor compatibility/staging objects missing';
  END IF;
END $baseline$;
